from __future__ import annotations
import argparse, hashlib, html, json, re, subprocess, sys, time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def digest(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def load(path): return json.loads(Path(path).read_text())
def tex(s):
    mapping={'\\':r'\textbackslash{}','&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}'}
    out=[]
    for part in re.split(r'(https?://[^\s]+|[0-9a-f]{40,64})',str(s)):
        if part.startswith(('https://','http://')):
            tail=''
            while part and part[-1] in '.,;':tail=part[-1]+tail;part=part[:-1]
            out.append(r'\url{'+part+'}'+tail)
        elif re.fullmatch('[0-9a-f]{40,64}',part):out.append(r'\texttt{'+r'\allowbreak{}'.join(part[i:i+12] for i in range(0,len(part),12))+'}')
        else:out.append(''.join(mapping.get(c,c) for c in part))
    return ''.join(out)
def fnum(x): return f'{x:,.6f}'.rstrip('0').rstrip('.') if isinstance(x,(int,float)) else str(x)
def para(blocks,text): blocks.append(('p',text))
def section(blocks,title): blocks.append(('h',title))
def table(blocks,headers,rows,caption): blocks.append(('table',(headers,rows,caption)))
def equation(blocks,latex,plain): blocks.append(('eq',(latex,plain)))
def code(blocks,text): blocks.append(('code',text))
def bullets(blocks,items): blocks.append(('list',items))
def readable(text):
    text=re.sub(r'\b(commit|blob|or|and|for|from|of|by|to|at|above|below|only|then|produces|before|after|capital|price|cost|world|received|recorded|all|leave|is|near|with)(?=[0-9])',r'\1 ',str(text))
    text=re.sub(r'(?<=[A-Za-z])(?=US\$|SIM USD)',' ',text)
    text=re.sub(r'(?<=[A-Za-z]),(?=[0-9])',', ',text)
    for a,b in [('US$','US$ '),('USD50','USD 50'),('USD10','USD 10'),('USD36','USD 36'),('SIM USD50','SIM USD 50'),('times3','times 3'),('=48','= 48'),('=24','= 24'),('in{','in {'),('or1/a','or 1/a'),('by1/a','by 1/a'),('October 2026','October 2026'),('May2025','May 2025'),('June2026','June 2026'),('August2026','August 2026'),('across119','across 119'),('received119','received 119'),('derivesR','derives R')]:text=text.replace(a,b)
    return text
def html_text(text):
    parts=[]
    for part in re.split(r'(https?://[^\s]+)',str(text)):
        if part.startswith(('http://','https://')):
            tail=''
            while part and part[-1] in '.,;':tail=part[-1]+tail;part=part[:-1]
            parts.append('<a href="'+html.escape(part,quote=True)+'">'+html.escape(part)+'</a>'+html.escape(tail))
        else:parts.append(html.escape(part))
    return ''.join(parts)

