def dynamic_summary(value):
    if isinstance(value,dict):
        for key in ('paper_summary','summary_for_paper','claim_summary'):
            if key in value: return value[key]
    return value

def render_tex(blocks,title,subtitle):
    out=[r'\documentclass[11pt,letterpaper]{article}',r'\usepackage[margin=0.82in,headheight=14pt]{geometry}',r'\usepackage[T1]{fontenc}',r'\usepackage{lmodern,microtype,amsmath,amssymb,booktabs,longtable,array,xcolor,fancyhdr,enumitem}',r'\usepackage[hyphens]{url}',r'\usepackage[colorlinks=true,urlcolor=blue,linkcolor=blue]{hyperref}',r'\definecolor{ink}{HTML}{122A3A}',r'\definecolor{accent}{HTML}{146B72}',r'\setlength{\parindent}{0pt}\setlength{\parskip}{6pt}',r'\setlength{\emergencystretch}{3em}',r'\pagestyle{fancy}\fancyhf{}\fancyhead[L]{\small\color{accent}AGI ALPHA / Consequential009}\fancyhead[R]{\small30 October 2026}\fancyfoot[C]{\small\thepage}',r'\setlist[itemize]{leftmargin=1.3em,topsep=2pt,itemsep=2pt}',r'\begin{document}',r'{\sffamily\LARGE\bfseries\color{ink}'+tex(title)+r'\par}',r'\vspace{6pt}{\large\color{accent}'+tex(subtitle)+r'\par}',r'\vspace{5pt}{\small Source-bound engineering study and conditional commercial execution\par}',r'\vspace{9pt}\hrule\vspace{9pt}',r'{\small\textbf{Evidence status.} Exact finite-model measurement enablement; conventional comparison retained; physical assurance and the complete commercial flywheel remain unestablished.}\vspace{4pt}']
    for kind,value in blocks:
        if kind=='h': out += [r'\section*{\color{accent}'+tex(value)+'}']
        elif kind=='p': out += [tex(value)+r'\par']
        elif kind=='eq': out += [r'\[ '+value[0]+r' \]']
        elif kind=='code': out += [r'\begin{quote}\footnotesize\ttfamily\raggedright '+r'\\'.join(tex(line) for line in value.splitlines())+r'\end{quote}']
        elif kind=='list': out += [r'\begin{itemize}']+[r'\item '+tex(x) for x in value]+[r'\end{itemize}']
        elif kind=='table':
            headers,rows,caption=value; n=len(headers); widths=[0.38,0.57] if n==2 else [0.36]+[0.55/(n-1)]*(n-1)
            out += [r'\begingroup\small\setlength{\tabcolsep}{4pt}\renewcommand{\arraystretch}{1.18}',r'\begin{longtable}{'+''.join('>{\\raggedright\\arraybackslash}p{'+str(w)+r'\linewidth}' for w in widths)+'}',r'\toprule '+' & '.join(r'\textbf{'+tex(x)+'}' for x in headers)+r'\\\midrule\endhead']
            out += [' & '.join(tex(c) for c in row)+r'\\' for row in rows]
            out += [r'\bottomrule\end{longtable}',r'{\footnotesize '+tex(caption)+r'\par}\endgroup']
        elif kind in ('commerce_dynamic','retention_dynamic'):
            summary=dynamic_summary(value)
            if isinstance(summary,str): out += [tex(summary)+r'\par']
            elif isinstance(summary,list): out += [tex(str(s))+r'\par' for s in summary]
            else: raise ValueError('PAPER_NARRATIVE_REQUIRED_NOT_JSON_SOURCE_LISTING')
    out += [r'\end{document}'];return '\n'.join(out)+'\n'

def render_html(blocks,title,subtitle):
    body=[]
    for kind,value in blocks:
        if kind=='h': body.append('<h2>'+html.escape(value)+'</h2>')
        elif kind=='p': body.append('<p>'+html_text(value)+'</p>')
        elif kind=='eq': body.append('<div class="equation">'+html.escape(value[1])+'</div>')
        elif kind=='code': body.append('<pre>'+html.escape(value)+'</pre>')
        elif kind=='list': body.append('<ul>'+''.join('<li>'+html.escape(x)+'</li>' for x in value)+'</ul>')
        elif kind=='table':
            headers,rows,caption=value
            body.append('<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table><p class="caption">'+html.escape(caption)+'</p></div>')
        else:
            summary=dynamic_summary(value)
            if not isinstance(summary,(str,list)):raise ValueError('PAPER_NARRATIVE_REQUIRED_NOT_JSON_SOURCE_LISTING')
            values=summary if isinstance(summary,list) else [summary]
            body += ['<p>'+html.escape(str(x))+'</p>' for x in values]
    css=':root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#edf2f5;color:#172e3b;font:18px/1.64 Georgia,serif}main{max-width:1080px;margin:auto;background:white;padding:64px 72px 90px}header{border-bottom:2px solid #146b72;margin-bottom:32px;padding-bottom:28px}h1{font:700 40px/1.12 system-ui,sans-serif;letter-spacing:-1px;margin:8px 0 16px}h2{font:650 25px/1.25 system-ui,sans-serif;color:#146b72;margin-top:40px}p{margin:16px 0;overflow-wrap:anywhere}.kicker{font:700 13px system-ui,sans-serif;letter-spacing:2px;color:#146b72}.subtitle{font:23px/1.4 system-ui,sans-serif}.status{font:15px/1.5 system-ui,sans-serif;background:#f4f2e9;border-left:4px solid #a9812d;padding:14px 18px}.tablewrap{overflow:auto;margin:24px 0}table{width:100%;border-collapse:collapse;font:15px/1.5 system-ui,sans-serif}th,td{text-align:left;padding:10px;border-bottom:1px solid #d9e2e8;vertical-align:top}th{background:#eaf3f3;color:#13464c}td:first-child{font-weight:600}pre,.equation{background:#f3f6f8;border-left:3px solid #6e9da6;padding:16px 20px;white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 ui-monospace,monospace}.equation{font:17px/1.6 Georgia,serif}.caption{font:13px/1.45 system-ui,sans-serif;color:#526774}a{color:#1459a0;overflow-wrap:anywhere}footer{border-top:1px solid #cedbe3;margin-top:48px;padding-top:20px;font:14px/1.5 system-ui,sans-serif}@media(max-width:720px){main{padding:28px 22px}h1{font-size:32px}h2{font-size:23px}body{font-size:17px}}@media print{body{background:white}main{padding:0;max-width:none}h2{break-after:avoid}table{break-inside:avoid}}'
    title_safe=html.escape(title)
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title_safe+'</title><style>'+css+'</style><main><header><div class="kicker">AGI ALPHA / CONSEQUENTIAL009 / 30 OCTOBER2026</div><h1>'+title_safe+'</h1><div class="subtitle">'+html.escape(subtitle)+'</div></header><div class="status"><strong>Evidence status:</strong> Exact finite-model measurement enablement. Conventional comparison retained. Physical assurance and the complete commercial flywheel remain unestablished.</div>'+''.join(body)+'<footer>Source-bound research edition. <a href="paper.pdf">PDF</a> · <a href="paper.tex">LaTeX</a> · <a href="SOURCE_MANIFEST.json">Input manifest</a></footer></main></html>\n'

def main():
    p=argparse.ArgumentParser();p.add_argument('--source-anchor',required=True);p.add_argument('--experiment',default='evidence/consequential009/resources/analog-r3/artifacts/REPORT.json');p.add_argument('--acceptance',required=True);p.add_argument('--retention',required=True);p.add_argument('--commerce',required=True);p.add_argument('--reference');p.add_argument('--reference-acceptance');p.add_argument('--extra-input',action='append',default=[]);p.add_argument('--output',default='docs/consequential009');p.add_argument('--no-compile',action='store_true');args=p.parse_args()
